using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Playables;using UnityEngine.Animations;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Sandbox.CharacterSystem;
public static class RepairV2Clothing {
 const string Prefab="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";
 const string MeshPath="Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_BodyBound.asset";
 static Vector3[] Skin(SkinnedMeshRenderer r,Transform root){var mesh=r.sharedMesh;var v=mesh.vertices;var m=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*mesh.bindposes[j]).ToArray();var o=new Vector3[v.Length];using(var c=mesh.GetBonesPerVertex())using(var w=mesh.GetAllBoneWeights()){int at=0;for(int j=0;j<v.Length;j++)for(int k=0;k<c[j];k++){var x=w[at++];o[j]+=m[x.boneIndex].MultiplyPoint3x4(v[j])*x.weight;}}return o;}
 static float[][] V(Vector3[] v)=>v.Select(p=>new[]{p.x,p.y,p.z}).ToArray();
 static Mesh Candidate(GameObject root,SkinnedMeshRenderer body,SkinnedMeshRenderer cloth){
 var neutral=Skin(cloth,root.transform);var mesh=UnityEngine.Object.Instantiate(cloth.sharedMesh);mesh.name="EthanV2_Outfit_BodyBound";
 // Facial channels on this outfit are neutral. Refuse to discard any actual shape motion.
 for(int i=0;i<mesh.blendShapeCount;i++){var delta=new Vector3[mesh.vertexCount];mesh.GetBlendShapeFrameVertices(i,0,delta,null,null);if(delta.Any(x=>x.sqrMagnitude>1e-12f))throw new Exception("Outfit has nonzero facial deltas; explicit delta rebinding required");}
 mesh.vertices=neutral.Select(x=>cloth.transform.InverseTransformPoint(root.transform.TransformPoint(x))).ToArray();
 mesh.bindposes=body.bones.Select(b=>b.worldToLocalMatrix*cloth.transform.localToWorldMatrix).ToArray();
 var weights=JObject.Parse(File.ReadAllText("Data/EthanV2/ClothingRepair/transferred_weights.json"))["weights"];
 mesh.boneWeights=weights.Select(row=>{var a=row.ToArray();var b=new BoneWeight();for(int i=0;i<a.Length;i++){int index=(int)a[i][0];float value=(float)a[i][1];switch(i){case 0:b.boneIndex0=index;b.weight0=value;break;case 1:b.boneIndex1=index;b.weight1=value;break;case 2:b.boneIndex2=index;b.weight2=value;break;case 3:b.boneIndex3=index;b.weight3=value;break;}}return b;}).ToArray();mesh.RecalculateBounds();return mesh;
 }
 public static object Audit(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents(Prefab);Mesh candidate=null;
 try{var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var body=all.Single(x=>x.name=="BAKED_body_lod0_mesh");var cloth=all.Single(x=>x.name=="BAKED_Outfits_LOD0");var oldMesh=cloth.sharedMesh;var oldBones=cloth.bones;var oldRoot=cloth.rootBone;
 candidate=Candidate(root,body,cloth);var animator=root.GetComponentInChildren<AnimationModule>(true).Animator;var bridge=root.GetComponent<CharacterSkeletonPoseBridge>();var samples=new List<object>();
 var defs=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion&&(d.name.ToLower().Contains("wav")||d.name.ToLower().Contains("think")||d.name.ToLower().Contains("idle"))).ToArray();
 foreach(var d in defs){var g=PlayableGraph.Create("Clothing Edit Mode audit");try{g.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(g,d.Clip);p.SetApplyFootIK(false);var output=AnimationPlayableOutput.Create(g,"pose",animator);output.SetSourcePlayable(p);g.Play();foreach(float f in new[]{0f,.125f,.25f,.375f,.5f,.625f,.75f,.875f}){p.SetTime(d.Clip.length*f);g.Evaluate(0);bridge.ApplyPose();cloth.sharedMesh=oldMesh;cloth.bones=oldBones;cloth.rootBone=oldRoot;var before=Skin(cloth,root.transform);cloth.sharedMesh=candidate;cloth.bones=body.bones;cloth.rootBone=body.rootBone;var after=Skin(cloth,root.transform);var matrices=cloth.bones.Select((bone,bi)=>{var m=root.transform.worldToLocalMatrix*bone.localToWorldMatrix*candidate.bindposes[bi]*cloth.transform.worldToLocalMatrix*root.transform.localToWorldMatrix;return new[]{m.m00,m.m01,m.m02,m.m10,m.m11,m.m12,m.m20,m.m21,m.m22};}).ToArray();samples.Add(new{name=d.name,fraction=f,body=V(Skin(body,root.transform)),before=V(before),after=V(after),matrices});}}finally{g.Destroy();}}
 File.WriteAllText("Data/EthanV2/ClothingRepair/pose_samples.json",JsonConvert.SerializeObject(samples));return new{samples=samples.Count,vertices=candidate.vertexCount};
 }finally{if(candidate)UnityEngine.Object.DestroyImmediate(candidate);PrefabUtility.UnloadPrefabContents(root);}}
 public static object Install(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");if(File.Exists(MeshPath))throw new Exception("Candidate already installed");
 Directory.CreateDirectory("Data/EthanV2/ClothingRepair/Before");File.Copy(Prefab,"Data/EthanV2/ClothingRepair/Before/Ethan_V2.prefab",false);
 var root=PrefabUtility.LoadPrefabContents(Prefab);try{var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var body=all.Single(x=>x.name=="BAKED_body_lod0_mesh");var cloth=all.Single(x=>x.name=="BAKED_Outfits_LOD0");var mesh=Candidate(root,body,cloth);Directory.CreateDirectory(Path.GetDirectoryName(MeshPath));AssetDatabase.CreateAsset(mesh,MeshPath);cloth.sharedMesh=mesh;cloth.bones=body.bones;cloth.rootBone=body.rootBone;cloth.quality=SkinQuality.Bone4;
 var mask=new HashSet<int>(JObject.Parse(File.ReadAllText("Data/EthanV2/ClothingRepair/body_mask.json"))["removeTriangles"].ToObject<int[]>());var covered=UnityEngine.Object.Instantiate(body.sharedMesh);covered.name="EthanV2_Body_ShirtCoverage";int offset=0;for(int sub=0;sub<covered.subMeshCount;sub++){var triangles=body.sharedMesh.GetTriangles(sub);var kept=new List<int>();for(int j=0;j<triangles.Length;j+=3){if(!mask.Contains(offset+j/3)){kept.Add(triangles[j]);kept.Add(triangles[j+1]);kept.Add(triangles[j+2]);}}covered.SetTriangles(kept,sub,false);offset+=triangles.Length/3;}AssetDatabase.CreateAsset(covered,"Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Body_ShirtCoverage.asset");body.sharedMesh=covered;
 PrefabUtility.SaveAsPrefabAsset(root,Prefab);AssetDatabase.SaveAssets();return new{installed=MeshPath,bones=cloth.bones.Length,hiddenCoveredBodyTriangles=mask.Count};}finally{PrefabUtility.UnloadPrefabContents(root);}
 }
}
